// XRec returns the record as it was last read from or written to the database (classic xRec),
// in the same database and company: xRec := rec.XRec(); if rec.No != xRec.No { … }. For a new
// record (never read) it is a blank record with the definition's defaults.
func (t *Insurance) XRec() *Insurance {
	x := &Insurance{db: t.db, company: t.company, dbType: t.dbType, temp: t.temp}
	x.InitRecord()
	insuranceFields.SetOldValues(x.fieldRef, t.oldValues)
	return x
}

// NewInsurance returns a Insurance record in the database and company of another
